<script>
document.addEventListener('DOMContentLoaded',function(){const input=document.getElementById('foto_profil'),preview=document.getElementById('profilePreview'),placeholder=document.getElementById('avatarPlaceholder'),name=document.getElementById('selectedFileName');if(!input||!preview)return;let previewUrl=null;input.addEventListener('change',function(){const file=this.files&&this.files[0];if(!file)return;if(!file.type.startsWith('image/')){alert('Pilih file gambar yang valid.');this.value='';return;}if(file.size>2*1024*1024){alert('Ukuran foto maksimal 2 MB.');this.value='';return;}if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);preview.src=previewUrl;preview.style.display='block';if(placeholder)placeholder.style.display='none';if(name)name.textContent='Foto dipilih: '+file.name;});});
</script>
